import 'dart:convert';
import 'dart:typed_data';

import 'package:flutter/widgets.dart';
import 'package:zmix/ui/poster_card.dart';

/// Real gradient "poster" artwork (invented fixture bytes) so golden renders
/// carry actual images and crop/aspect are verifiable.
final Map<String, Uint8List> fixtureArt = {
  'a': base64Decode(''),
  'b': base64Decode(''),
  'c': base64Decode(''),
};

/// Fixture thumbnail URL; the last segment selects the artwork key.
String artUrl(String key) => 'https://fixture.invalid/art/$key.jpg';

/// Point PosterCard at in-memory fixture artwork instead of the network.
void installFixtureArtwork() {
  PosterCard.debugImageProvider = (url) {
    final key = Uri.parse(url).pathSegments.last.replaceAll('.jpg', '');
    return MemoryImage(fixtureArt[key] ?? fixtureArt['a']!);
  };
}
